//! The production node against `spec/tests/` (Master Prompt 15 §2).
//!
//! The vectors are generated by `crates/spec-ref`, which shares no code with
//! this crate. Every case is replayed here through the real entry points —
//! `Transaction::from_bytes`, real hybrid signatures, `StateDB::apply_block`,
//! `maya_fee_market` — and any disagreement fails with the case id.
//!
//! `spec/tests/keys.json` is the one file this side produces: the hybrid public
//! keys the node derives from four fixed seeds. The reference recomputes each
//! address from its key, so a divergence in address derivation shows up on
//! both sides. Regenerate with `MAYA_SPEC_BLESS=1`; otherwise it is checked.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::collections::BTreeMap;
use std::path::PathBuf;

use custom_l1_node::core::{Block, BlockHeader, ChainTag, Transaction, TxOutput};
use custom_l1_node::crypto::hybrid::{HybridSigningKey, signing_key_from_seed};
use custom_l1_node::crypto::pow::target_from_leading_zero_bits;
use custom_l1_node::error::NodeError;
use custom_l1_node::state::mining::{DagProfile, MiningRecord, share_header};
use custom_l1_node::state::{Account, Address, BlockContext, StateDB};
use serde_json::{Value, json};

mod common;

const KEYS: u8 = 4;

fn spec(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../spec/tests")
        .join(name)
}

fn load(name: &str) -> Value {
    serde_json::from_str(&std::fs::read_to_string(spec(name)).expect(name)).unwrap()
}

/// A balance: a 256-bit decimal string (ADR-046), not a u64.
fn amount(v: &Value) -> primitive_types::U256 {
    primitive_types::U256::from_dec_str(v.as_str().unwrap()).unwrap()
}

/// Vectors carry every u64 as a decimal string (see spec-vectors).
fn num(v: &Value) -> u64 {
    v.as_str()
        .expect("u64 fields are decimal strings")
        .parse()
        .expect("decimal u64")
}

fn unhex(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap()
}

/// `k0..k3` from seeds `[1; 32] .. [4; 32]`.
fn node_keys() -> BTreeMap<String, HybridSigningKey> {
    (0..KEYS)
        .map(|i| {
            (
                format!("k{i}"),
                signing_key_from_seed(&[i + 1; 32]).unwrap(),
            )
        })
        .collect()
}

#[test]
fn key_table_matches_the_node() {
    let keys: Vec<Value> = node_keys()
        .iter()
        .enumerate()
        .map(|(i, (name, key))| {
            let mut pk = Vec::new();
            key.public_key().encode_into(&mut pk);
            json!({"name": name, "seed": hex::encode([u8::try_from(i).unwrap() + 1; 32]), "public_key": hex::encode(pk), "address": hex::encode(key.address())})
        })
        .collect();
    let doc = json!({"format": 1, "note": "hybrid ML-DSA-65 + SLH-DSA-SHA2-128s keys from custom_l1_node::crypto::hybrid::signing_key_from_seed; produced by crates/node/tests/conformance.rs", "keys": keys});
    let text = serde_json::to_string_pretty(&doc).unwrap() + "\n";
    if std::env::var("MAYA_SPEC_BLESS").is_ok() {
        std::fs::write(spec("keys.json"), &text).unwrap();
    }
    assert_eq!(
        std::fs::read_to_string(spec("keys.json")).unwrap(),
        text,
        "keys.json is stale: MAYA_SPEC_BLESS=1"
    );
}

fn address(keys: &BTreeMap<String, HybridSigningKey>, name: &str) -> Address {
    keys.get(name).map_or_else(
        || unhex(name).try_into().unwrap(),
        HybridSigningKey::address,
    )
}

fn signed(keys: &BTreeMap<String, HybridSigningKey>, t: &Value) -> Transaction {
    let outputs = t["outputs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|o| TxOutput {
            amount: amount(&o["amount"]),
            recipient: address(keys, o["to"].as_str().unwrap()),
        })
        .collect();
    let mut tx = Transaction::new(vec![], outputs, num(&t["nonce"]));
    // "other-chain" (TX-5) is a valid signature for some other genesis.
    let chain = if t["signature"] == "other-chain" {
        ChainTag::from_genesis([0x99; 32])
    } else {
        common::test_chain()
    };
    tx.sign(&keys[t["from"].as_str().unwrap()], &chain).unwrap();
    if t["signature"] == "invalid" {
        // One bit inside the SLH-DSA half, which ends a v5 frame.
        let mut bytes = tx.to_bytes();
        let at = bytes.len() - 100;
        bytes[at] ^= 1;
        tx = Transaction::from_bytes(&bytes).unwrap();
    }
    tx
}

fn kind(e: &NodeError) -> &'static str {
    match e {
        NodeError::InvalidNonce { .. } => "InvalidNonce",
        NodeError::InsufficientBalance { .. } => "InsufficientBalance",
        NodeError::BalanceOverflow => "BalanceOverflow",
        NodeError::MissingSignature
        | NodeError::SignatureVerification
        | NodeError::HashSignatureVerification
        | NodeError::MalformedPublicKey => "BadSignature",
        NodeError::StateRootMismatch { .. } => "StateRootMismatch",
        _ => "Other",
    }
}

fn block_of(transactions: Vec<Transaction>) -> Block {
    let header = BlockHeader {
        version: 0,
        prev_hash: [0; 32],
        state_root: [0; 32],
        timestamp: 1_756_252_800,
        nonce: 0,
        difficulty_target: target_from_leading_zero_bits(0),
        tx_root: [0; 32],
    };
    Block::new(header, transactions)
}

fn run_stf_case(keys: &BTreeMap<String, HybridSigningKey>, case: &Value) {
    let id = case["id"].as_str().unwrap();
    let dir = tempfile::TempDir::new().unwrap();
    let db = StateDB::open(dir.path()).unwrap();
    common::bind(&db);
    for a in case["pre"].as_array().unwrap() {
        let acc = Account {
            balance: amount(&a["balance"]),
            nonce: num(&a["nonce"]),
        };
        db.put_account(&address(keys, a["account"].as_str().unwrap()), &acc)
            .unwrap();
    }
    assert_eq!(
        hex::encode(db.state_root().unwrap()),
        case["pre_root"].as_str().unwrap(),
        "{id}: pre_root"
    );
    let txs = case["block"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| signed(keys, t))
        .collect();
    let expect = &case["expect"];
    // CON-4: a case declaring a state root goes through the path that checks it.
    let applied = match case["declared_state_root"].as_str() {
        Some(declared) => {
            let mut block = block_of(txs);
            block.header.state_root = unhex(declared).try_into().unwrap();
            db.apply_block_checked(&block, BlockContext::GENESIS)
        }
        None => db.apply_block(&block_of(txs), BlockContext::GENESIS),
    };
    match applied {
        Ok(root) => {
            assert_eq!(
                expect["result"], "ok",
                "{id}: node accepted a block the reference rejects ({})",
                expect["error"]
            );
            assert_eq!(
                hex::encode(root),
                expect["post_root"].as_str().unwrap(),
                "{id}: post_root"
            );
            for a in expect["post"].as_array().unwrap() {
                let acc = db
                    .get_account(&unhex(a["address"].as_str().unwrap()).try_into().unwrap())
                    .unwrap();
                assert_eq!(
                    (acc.balance, acc.nonce),
                    (amount(&a["balance"]), num(&a["nonce"])),
                    "{id}: post account"
                );
            }
        }
        Err(e) => {
            assert_eq!(
                expect["result"], "error",
                "{id}: node rejected a valid block: {e}"
            );
            assert_eq!(
                kind(&e),
                expect["error"].as_str().unwrap(),
                "{id}: wrong error kind ({e})"
            );
            assert_eq!(
                hex::encode(db.state_root().unwrap()),
                case["pre_root"].as_str().unwrap(),
                "{id}: a refused block changed state"
            );
        }
    }
}

#[test]
fn state_transition_vectors() {
    let keys = node_keys();
    let doc = load("state_transitions.json");
    let cases = doc["cases"].as_array().unwrap();
    for case in cases {
        run_stf_case(&keys, case);
    }
    println!(
        "{} state-transition vectors agree with the reference",
        cases.len()
    );
}

#[test]
fn encoding_vectors() {
    let doc = load("encoding.json");
    for case in doc["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let bytes = unhex(case["bytes"].as_str().unwrap());
        match (
            Transaction::from_bytes(&bytes),
            case["expect"]["result"].as_str().unwrap(),
        ) {
            (Ok(tx), "ok") => {
                assert_eq!(tx.to_bytes(), bytes, "{id}: not canonical");
                assert_eq!(
                    hex::encode(tx.txid()),
                    case["expect"]["txid"].as_str().unwrap(),
                    "{id}: txid"
                );
                assert_eq!(
                    hex::encode(tx.sender()),
                    case["expect"]["sender"].as_str().unwrap(),
                    "{id}: sender"
                );
                assert_eq!(tx.nonce, num(&case["expect"]["nonce"]), "{id}: nonce");
                let tag: [u8; 32] = unhex(case["chain_tag"].as_str().unwrap())
                    .try_into()
                    .expect("a 32-byte chain tag");
                assert_eq!(
                    blake3::hash(&tx.signing_bytes(&ChainTag::from_genesis(tag)))
                        .to_hex()
                        .as_str(),
                    case["expect"]["signing_bytes_blake3"].as_str().unwrap(),
                    "{id}: signing bytes (TX-3, TX-5)"
                );
            }
            (Err(NodeError::Decode(_)), "error") => {}
            (other, want) => panic!("{id}: expected {want}, node gave {other:?}"),
        }
    }
}

#[test]
fn fee_vectors() {
    let doc = load("fees.json");
    for case in doc["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let n = |k: &str| num(&case[k]);
        match case["fn"].as_str().unwrap() {
            "split" => {
                let s = maya_fee_market::split(
                    maya_ledger_math::Amount::from_u64(n("base_fee_paid")),
                    maya_ledger_math::Amount::from_u64(0),
                    n("treasury_bps"),
                );
                assert_eq!(
                    (s.burned, s.treasury),
                    (
                        maya_ledger_math::Amount::from_u64(num(&case["expect"]["burned"])),
                        maya_ledger_math::Amount::from_u64(num(&case["expect"]["treasury"]))
                    ),
                    "{id}"
                );
            }
            "next_base_fee" => {
                // 256-bit decimal strings: FEE-3 saturates at 2^256 - 1.
                let wide = |v: &Value| {
                    maya_stateless_core::amount::to_amount(
                        primitive_types::U256::from_dec_str(v.as_str().expect("decimal string"))
                            .expect("fits 256 bits"),
                    )
                };
                let got = maya_fee_market::next_base_fee(
                    wide(&case["parent_base_fee"]),
                    n("parent_size"),
                    n("target"),
                    n("denominator"),
                    wide(&case["floor"]),
                );
                assert_eq!(got, wide(&case["expect"]), "{id}");
            }
            "admit" => {
                let c = maya_fee_market::FeeConfig::TESTING;
                assert_eq!(
                    maya_ledger_math::Amount::from_u64(n("base_fee")),
                    c.initial_base_fee,
                    "{id}: vectors assume the testing config's initial base fee"
                );
                let tx = maya_fee_market::TxFee {
                    size_bytes: n("size_bytes"),
                    max_fee: maya_ledger_math::Amount::from_u64(n("max_fee")),
                    max_tip: maya_ledger_math::Amount::from_u64(0),
                };
                let got = maya_fee_market::apply_block_fees(
                    &c,
                    1,
                    None,
                    &[tx],
                    &[maya_fee_market::FeeClaim {
                        beneficiary: [7; 32],
                    }],
                );
                match (got, case["expect"]["result"].as_str().unwrap()) {
                    (Ok(_), "ok")
                    | (Err(maya_fee_market::FeeError::Underpriced { .. }), "error") => {}
                    (other, want) => panic!("{id}: expected {want}, fee market gave {other:?}"),
                }
            }
            other => panic!("{id}: unknown fn {other}"),
        }
    }
}

fn header_of(h: &Value) -> BlockHeader {
    let arr = |k: &str| -> [u8; 32] { unhex(h[k].as_str().unwrap()).try_into().unwrap() };
    BlockHeader {
        version: u8::try_from(h["version"].as_u64().unwrap()).unwrap(),
        prev_hash: arr("prev_hash"),
        state_root: arr("state_root"),
        timestamp: num(&h["timestamp"]),
        nonce: num(&h["nonce"]),
        difficulty_target: arr("difficulty_target"),
        tx_root: arr("tx_root"),
    }
}

#[test]
fn header_vectors() {
    let doc = load("headers.json");
    for case in doc["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let header = header_of(&case["header"]);
        let expect = &case["expect"];
        let Some(txs) = case["transactions"].as_array() else {
            assert_eq!(
                hex::encode(header.serialize()),
                expect["bytes"].as_str().unwrap(),
                "{id}: bytes"
            );
            assert_eq!(
                hex::encode(header.id()),
                expect["id"].as_str().unwrap(),
                "{id}: id"
            );
            continue;
        };
        // Built directly, not through Block::new, which would overwrite tx_root.
        let transactions = txs
            .iter()
            .map(|t| Transaction::from_bytes(&unhex(t.as_str().unwrap())).unwrap())
            .collect();
        let block = Block {
            header,
            transactions,
        };
        match (block.check_tx_root(), expect["result"].as_str().unwrap()) {
            (Ok(()), "ok") => assert_eq!(
                hex::encode(block.tx_root()),
                expect["tx_root"].as_str().unwrap(),
                "{id}: tx_root"
            ),
            (Err(_), "error") => {}
            (other, want) => panic!("{id}: expected {want}, node gave {other:?}"),
        }
    }
}

/// The node's mining schedule against `spec/tests/mining.json` (MINE-1 .. 3).
#[test]
fn mining_vectors() {
    use custom_l1_node::state::mining::MiningGenesis;
    let doc = load("mining.json");
    for case in doc["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let record = |reward: &str, tail: &str, h: &str, blocks: u64| {
            let mut r = MiningGenesis {
                initial_epoch_reward: primitive_types::U256::from(1_000_000),
                halving_epochs: case.get(h).map_or(1, num),
                tail_epoch_reward: primitive_types::U256::zero(),
                miner_share_bps: 7_000,
                target_shares: 1,
                max_shares_per_block: 1,
                initial_target: "0f".repeat(32),
                dag: DagProfile::Testing,
            }
            .record(blocks)
            .unwrap();
            // Set the amounts directly: the vectors include schedules that
            // genesis validation (the 2^192 ceiling) refuses.
            r.initial_epoch_reward = to_amount(amount(&case[reward]));
            r.tail_epoch_reward = to_amount(amount(&case[tail]));
            r
        };
        match case["fn"].as_str().unwrap() {
            "epoch_reward" => {
                let r = record("initial", "tail", "halving_epochs", 600);
                assert_eq!(
                    r.epoch_reward(num(&case["epoch"])),
                    to_amount(amount(&case["expect"])),
                    "{id}"
                );
            }
            "split" => {
                let mut r = record("reward", "reward", "halving_epochs", 600);
                r.halving_epochs = 1;
                r.miner_share_bps = num(&case["miner_bps"]).min(10_000);
                assert_eq!(
                    r.miner_budget(0),
                    to_amount(amount(&case["expect"]["miners"])),
                    "{id}"
                );
                assert_eq!(
                    r.validator_reward(0),
                    to_amount(amount(&case["expect"]["committee"])),
                    "{id}"
                );
            }
            "lifetime_emission" => {
                let r = record(
                    "initial",
                    "tail",
                    "halving_epochs",
                    num(&case["epoch_blocks"]),
                );
                let expect = (case["expect"]["result"] == "ok")
                    .then(|| to_amount(amount(&case["expect"]["total"])));
                assert_eq!(r.lifetime_emission(), expect, "{id}");
            }
            "share_reward" => {
                let mut r = bare_record();
                r.initial_epoch_reward = to_amount(amount(&case["reward"]));
                r.miner_share_bps = num(&case["miner_bps"]);
                r.target_shares = num(&case["target_shares"]);
                r.paid = to_amount(amount(&case["paid"]));
                assert_eq!(r.share_reward(), to_amount(amount(&case["expect"])), "{id}");
            }
            "retarget" => {
                let mut r = bare_record();
                r.target = be32(&case["target"]);
                r.target_limit = be32(&case["target_limit"]);
                r.target_shares = num(&case["target_shares"]);
                r.shares = num(&case["shares"]);
                r.spent_after = num(&case["spent_after"]);
                r.epoch_blocks = num(&case["epoch_blocks"]);
                assert_eq!(r.retarget(), be32(&case["expect"]), "{id}");
            }
            "validate" => {
                let r = MiningRecord {
                    initial_epoch_reward: to_amount(amount(&case["initial"])),
                    halving_epochs: num(&case["halving_epochs"]),
                    tail_epoch_reward: to_amount(amount(&case["tail"])),
                    miner_share_bps: num(&case["miner_share_bps"]),
                    target_shares: num(&case["target_shares"]),
                    max_shares_per_block: num(&case["max_shares_per_block"]),
                    epoch_blocks: num(&case["epoch_blocks"]),
                    spent_after: num(&case["spent_after"]),
                    target: be32(&case["target"]),
                    target_limit: be32(&case["target_limit"]),
                    ..bare_record()
                };
                let ok = r.validate().is_ok();
                assert_eq!(ok, case["expect"]["result"] == "ok", "{id}");
            }
            "share_header" => {
                let header = share_header(
                    &hash32(&case["chain_tag"]),
                    num(&case["epoch"]),
                    &hash32(&case["anchor"]),
                    &hash32(&case["miner"]),
                );
                assert_eq!(hex::encode(header), case["expect"], "{id}");
            }
            "meets_target" => {
                let met = custom_l1_node::crypto::pow::meets_target(
                    &hash32(&case["digest"]),
                    &hash32(&case["target"]),
                );
                assert_eq!(met, case["expect"]["result"] == "ok", "{id}");
            }
            other => panic!("{id}: unknown fn {other}"),
        }
    }
}

/// A 256-bit decimal field of a mining vector, as the node's big-endian bytes.
fn be32(v: &Value) -> [u8; 32] {
    let mut out = [0u8; 32];
    amount(v).to_big_endian(&mut out);
    out
}

/// A 32-byte hex field of a mining vector.
fn hash32(v: &Value) -> [u8; 32] {
    unhex(v.as_str().unwrap()).try_into().unwrap()
}

/// A record whose fields a case then sets; the rest are inert defaults.
fn bare_record() -> MiningRecord {
    MiningRecord {
        initial_epoch_reward: to_amount(primitive_types::U256::zero()),
        halving_epochs: 1,
        tail_epoch_reward: to_amount(primitive_types::U256::zero()),
        miner_share_bps: 0,
        target_shares: 1,
        max_shares_per_block: 1,
        dag: DagProfile::Testing,
        epoch_blocks: 1,
        epoch: 0,
        anchor: [0; 32],
        target: [0; 32],
        shares: 0,
        paid: to_amount(primitive_types::U256::zero()),
        spent_after: 0,
        target_limit: [0xff; 32],
    }
}

fn to_amount(v: primitive_types::U256) -> maya_ledger_math::Amount {
    let mut bytes = [0u8; 32];
    v.to_little_endian(&mut bytes);
    maya_ledger_math::Amount::from_le_bytes(bytes)
}
